        require(fund > 0);
        require(address(this).balance >= val);
        // fund c so it holds leftover Ether before go() is invoked
        (bool funded, ) = address(c).call{value: fund}("");
        require(funded);
        bool ok;
        (, ok) = address(c).call{value: val}(abi.encodeWithSignature("go()"));
        assert(ok);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function test(uint256 b, uint256 v) public {
        require(address(this).balance >= b + v);

        address ow = c.owner();
        uint256 ownerBefore = ow.balance;

