contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(uint256 extra) public {
        require(extra > 0);
        require(address(this).balance >= extra + 1 ether);

        // park extra funds in c via its payable fallback
        (bool ok, ) = address(c).call{value: extra}("");
        require(ok);

        // drive go() with 1 ether
        c.go{value: 1 ether}();

        // P sweeps everything: c must be left with zero balance
        assert(address(c).balance == 0);
    }

    receive() external payable {}
    fallback() external payable {}
}
